        public float pivotX = 0.5f;
        [DefaultValue(0.5f)]
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public float pivotY = 0.5f;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public int borderLeft;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public int borderBottom;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public int borderRight;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
